// Package config reads the user-level intropy configuration file — settings
// that belong to a person and a machine rather than to a project, such as
// which GitOps repository to deploy through.
//
// Project-scoped state lives elsewhere and is found by walking up from the
// working directory (skills.json, .intropy/scaffold.json); this package is
// only for the single per-user file.
//
// Precedence is flag > environment > file > zero. The file is optional: a
// missing one yields the zero Config, because a user who passes every setting
// on the command line should never be told to create a config file. A file
// that exists but cannot be parsed is an error — silently ignoring it would
// mean a typo'd key looks exactly like a setting that was never set.
package config

import (
	"cmp"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

const (
	// EnvGitopsRepo overrides gitopsRepo. Settings this CLI owns are
	// namespaced with INTROPY_ so they cannot collide with other tools.
	EnvGitopsRepo = "INTROPY_GITOPS_REPO"

	// EnvArgocdServer and EnvArgocdAuthToken are deliberately *not*
	// namespaced: they are the argocd CLI's own variables, and reading them
	// means an existing Argo setup works here with no extra configuration.
	// Borrowed, not ours — do not rename them.
	EnvArgocdServer    = "ARGOCD_SERVER"
	EnvArgocdAuthToken = "ARGOCD_AUTH_TOKEN"

	dirName  = "intropy"
	fileName = "config.yaml"
)

// Config is the on-disk file. Fields are optional; every one of them can also
// be supplied by flag or environment variable.
type Config struct {
	// GitopsRepo is the clone URL of the GitOps repository that holds the
	// deployment overlays.
	GitopsRepo string `yaml:"gitopsRepo"`

	// ArgocdServer is a fallback for repositories whose deploy.yaml does not
	// name an ArgoCD server. deploy.yaml wins when both are present, since it
	// travels with the repository the overlays live in.
	ArgocdServer string `yaml:"argocdServer"`
}

// Flags carries the command-line values that take precedence over everything
// else. Empty fields fall through to the environment and then the file.
type Flags struct {
	GitopsRepo   string
	ArgocdServer string
}

// Dir returns the directory holding the configuration file. It honours
// XDG_CONFIG_HOME and otherwise uses ~/.config on every platform — matching
// argocd and gh rather than os.UserConfigDir, which on macOS would resolve to
// ~/Library/Application Support and put this file somewhere no one would look
// for it.
func Dir() (string, error) {
	if base := os.Getenv("XDG_CONFIG_HOME"); base != "" {
		return filepath.Join(base, dirName), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("locate home directory: %w", err)
	}
	return filepath.Join(home, ".config", dirName), nil
}

// Path returns the full path of the configuration file, whether or not it
// exists. Use it in error messages so users know which file to create.
func Path() (string, error) {
	dir, err := Dir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, fileName), nil
}

// Load reads the configuration file. A missing file yields the zero Config
// and no error; anything else — unreadable, malformed, or carrying unknown
// keys — is an error naming the path.
func Load() (Config, error) {
	path, err := Path()
	if err != nil {
		return Config{}, err
	}
	return loadFile(path)
}

func loadFile(path string) (Config, error) {
	f, err := os.Open(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return Config{}, nil
		}
		return Config{}, fmt.Errorf("read %s: %w", path, err)
	}
	defer f.Close()

	var cfg Config
	dec := yaml.NewDecoder(f)
	// Reject unknown keys: a misspelled setting that is silently dropped is
	// indistinguishable from one that was never set, and produces a confusing
	// failure much further along.
	dec.KnownFields(true)
	if err := dec.Decode(&cfg); err != nil {
		if errors.Is(err, io.EOF) {
			// An empty file is a legitimate way to say "no settings".
			return Config{}, nil
		}
		return Config{}, fmt.Errorf("parse %s: %w", path, err)
	}
	return cfg, nil
}

// Resolve layers flag values over the environment and then the file. The
// result is what the command should actually use.
func (c Config) Resolve(flags Flags) Config {
	return Config{
		GitopsRepo:   cmp.Or(flags.GitopsRepo, os.Getenv(EnvGitopsRepo), c.GitopsRepo),
		ArgocdServer: cmp.Or(flags.ArgocdServer, os.Getenv(EnvArgocdServer), c.ArgocdServer),
	}
}

// RequireGitopsRepo returns the resolved GitOps repository URL, or an error
// listing every way it can be supplied.
func (c Config) RequireGitopsRepo() (string, error) {
	if c.GitopsRepo != "" {
		return c.GitopsRepo, nil
	}
	path, err := Path()
	if err != nil {
		path = filepath.Join("~", ".config", dirName, fileName)
	}
	return "", fmt.Errorf("no GitOps repository configured; pass --gitops-repo, set %s, or add gitopsRepo to %s", EnvGitopsRepo, path)
}

package template

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
)

// DefaultLibrary reports the official template library the CLI targets.
//
// Callers outside this package need it to describe what they fetched; the
// constants themselves stay unexported so defaults_test.go remains the one place
// a change to the library source has to be acknowledged.
func DefaultLibrary() (owner, repo string) {
	return defaultTemplateOwner, defaultTemplateRepo
}

// LibraryOptions selects which template library to fetch.
type LibraryOptions struct {
	// Version pins a release tag. Empty resolves the latest release.
	Version string

	HTTP      *http.Client
	UserAgent string
	Stderr    io.Writer

	// Test overrides. Production callers leave these zero-valued.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// Library is a template library extracted on disk at one resolved version.
//
// It exists so a caller rendering several templates pays for one download and
// gets one version across all of them — a component's manifests and its system's
// shared manifests drifting apart by a release would be a subtle, ugly bug. It
// also keeps the on-disk layout of a template package private to this package.
//
// The caller owns the returned Library and must Close it.
type Library struct {
	Owner   string
	Repo    string
	Version string

	root    string
	cleanup func()
}

// FetchLibrary resolves the release tag, downloads the library tarball and
// extracts it.
func FetchLibrary(ctx context.Context, opts LibraryOptions) (*Library, error) {
	owner, repo := DefaultLibrary()
	if opts.Owner != "" {
		owner = opts.Owner
	}
	if opts.Repo != "" {
		repo = opts.Repo
	}
	userAgent := opts.UserAgent
	if userAgent == "" {
		userAgent = "intropy-cli"
	}

	gh := newConfiguredGitHub(opts.HTTP, userAgent, opts.GitHubBaseURL)
	tag, err := gh.ResolveTag(ctx, owner, repo, opts.Version)
	if err != nil {
		return nil, err
	}
	if opts.Stderr != nil {
		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", owner, repo, tag)
	}

	rc, err := gh.Tarball(ctx, owner, repo, tag)
	if err != nil {
		return nil, err
	}
	defer rc.Close()

	tmpDir, err := os.MkdirTemp("", "intropy-library-*")
	if err != nil {
		return nil, err
	}
	cleanup := func() { _ = os.RemoveAll(tmpDir) }
	if err := ExtractTarGz(rc, tmpDir); err != nil {
		cleanup()
		return nil, err
	}
	return &Library{Owner: owner, Repo: repo, Version: tag, root: tmpDir, cleanup: cleanup}, nil
}

// Close removes the extracted copy.
func (l *Library) Close() {
	if l != nil && l.cleanup != nil {
		l.cleanup()
	}
}

// Ref describes the fetched library, for logs and result records.
func (l *Library) Ref() string {
	return fmt.Sprintf("%s/%s@%s", l.Owner, l.Repo, l.Version)
}

// Open loads one template's manifest and returns it with its skeleton root.
//
// The name is validated as a single path segment before it is joined, because it
// is user input turned into a path inside the extracted tarball.
func (l *Library) Open(name string) (*Template, string, error) {
	if err := validateTemplateName(name); err != nil {
		return nil, "", err
	}
	templateRoot := filepath.Join(l.root, name)
	if info, err := os.Stat(templateRoot); err != nil || !info.IsDir() {
		return nil, "", fmt.Errorf("template %q not found in %s", name, l.Ref())
	}
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, "", fmt.Errorf("%s in %s: %w", name, l.Ref(), err)
	}
	skeleton := filepath.Join(templateRoot, templateSkeletonDir)
	if info, err := os.Stat(skeleton); err != nil || !info.IsDir() {
		return nil, "", fmt.Errorf("template %q is missing %s/ directory", name, templateSkeletonDir)
	}
	return tmpl, skeleton, nil
}

